'use strict';
/* FRC Manager — guided tours (once per game: first Kickoff, first event, first match) and the categorized How to play guide */
(function () {
  const U = G.U, D = G.Data, h = U.esc, UI = G.UI;
  const ic = (n, s) => UI.icon(n, s || 16);
  const flow = list => '<div class="diagram">' + list.map((x, i) => (i ? '<span class="arr">→</span>' : '') + '<span class="node">' + ic(x[0], 14) + h(x[1]) + '</span>').join('') + '</div>';

  // =====================================================================
  // Tours: a card next to the highlighted control, Back / Next / Skip, and "Don't show tutorials"
  // =====================================================================
  const TOURS = {
    season: () => [
      { icon: 'trophy', title: 'Your season at a glance', body: 'You are the Lead Mentor. You don\'t drive: you run the program behind the robot.', diagram: flow([['design', 'Plan the week'], ['play', 'Continue'], ['event', 'Compete'], ['history', 'Season review']]) },
      { sel: '[data-act="continue"]', icon: 'play', title: 'Continue = next turn', points: ['One turn is a <b>week</b> in season and a <b>month</b> in the offseason.', 'Team hours are spent when you press it.', 'Budget, morale, support, reputation and (in season) fatigue sit up here.'] },
      { sel: '.nav[data-arg="hq"]', screen: 'hq', icon: 'hq', title: 'Headquarters', points: ['This week\'s to-do and your next event.', 'Robot, projects, money and goals in one place.'] },
      { sel: '.nav[data-arg="inbox"]', icon: 'inbox', title: 'Inbox', points: ['News, results and decisions.', 'Some messages take an optional <b>reply</b> with a small effect.'] },
      { sel: '.nav[data-arg="design"]', screen: 'design', icon: 'design', title: 'Design Office', points: ['Pick a <b>concept</b> for each subsystem, then upgrade it. <b>Build copy</b> makes more of a finished design.', 'Projects share the team hours. Give a project <b>extra hours</b> to raise its quality.', 'Leave about <b>10% idle</b> each week to keep fatigue steady.'] },
      { sel: '.nav[data-arg="garage"]', screen: 'garage', icon: 'garage', title: 'Garage: two robots', points: ['<b>Robot 1</b> and <b>Robot 2</b>: pick which one competes and which one the drivers practice on.', 'Fit built subsystems to either robot; spares wait in storage.', 'Drivers need practice with each new mechanism (<b>familiarity</b>).', 'A cheap <b>test chassis</b> on Robot 2 gives testing hours, defense drills and an electrical shakedown from the first weeks.'] },
      { sel: '.nav[data-arg="parts"]', screen: 'parts', icon: 'parts', title: 'Inventory', points: ['Every build needs motors and a control system. Kickoff brings a small free kit.', 'Two vendors: a premium one (<b>Sterling</b> until 2019, <b>Apex</b> from 2020) and <b>Lumen</b> (value). Mixing them costs a little.', 'In season, parts often <b>sell out</b>: stock up before Kickoff.'] },
      { sel: '.nav[data-arg="workshop"]', icon: 'workshop', title: 'Workshop', points: ['Facilities speed up projects and add project slots. They wear down: renovate or upgrade.', 'Every facility takes <b>floor space</b>. The school gives the team more room when Program Support is high at a season review.'] },
      { sel: '.nav[data-arg="team"]', icon: 'team', title: 'Team', points: ['Choose the five-person drive team, or use "Auto-pick best".', 'Outreach and fundraising (each repeat in a month pays less), feeder programs and your Impact Award rating.'] },
      { sel: '.nav[data-arg="finance"]', icon: 'finance', title: 'Finance', points: ['Sign sponsors in October; they pay at Kickoff.', 'The Sponsor funding card shows this season\'s bonuses and what next season looks like.', 'In season you may go into debt; under ' + U.money(D.STEM_FUND.below) + ' the STEM fund can help.'] },
      { sel: '.nav[data-arg="calendar"]', icon: 'calendar', title: 'Calendar', points: ['The whole year with filters.', 'Register for regionals, or for your district\'s events (weeks 1–6). Week 7 is a rest week before the Championship, or District Championship week.', 'Withdraw a month ahead for a half refund.'] },
      { sel: '.helpq', icon: 'help', title: 'Need more?', points: ['The <b>?</b> on every screen opens its guide.', 'The full guide is in <b>☰ → How to play</b>.'] }
    ],
    event: () => [
      { icon: 'event', title: 'Your first event', body: 'An event runs in stages:', diagram: flow([['spare', 'Practice'], ['play', 'Qualifications'], ['team', 'Alliance selection'], ['trophy', 'Playoffs']]) },
      { sel: '.card .ct', icon: 'spare', title: 'Practice day', points: ['Spend practice blocks on tuning, driver reps, auto, scouting or a <b>Systems Shakedown</b> (rebuilds the robot to 100%).'] },
      { sel: '.card.mt .ct', icon: 'spare', title: 'Pit crew', points: ['Repairs between matches use <b>spare parts</b>. Buying them here costs double.', 'A spare subsystem in storage identical to the robot\'s can be <b>swapped in</b> to restore it to 100%.'] },
      { icon: 'fatigue', title: 'Fatigue at events', points: ['Team fatigue is locked in when the event starts.', 'Tired teams make mistakes: wrong auto, flat battery, a loose bumper, mixed-up scouting. See the <b>Incidents</b> and <b>Scouting</b> tabs.', 'A <b>Technician</b> on the drive team (Team page) catches some of them and speeds up repairs.'] }
    ],
    match: () => [
      { icon: 'play', title: 'Your first match', points: ['Set the plan: pace, role (score / defend / feed), target and endgame.', 'Watch it live or simulate it.'] },
      { icon: 'mentors', title: 'Coach Calls', points: ['A few calls per match: change pace or role, go for the endgame, reset a faulted robot.', 'Defense follows the real rules: pins are limited and some zones are protected.'] }
    ]
  };
  const Tut = UI.Tut = { cur: null };
  Tut.enabled = () => !G.Save.settings().noTut;
  Tut.setEnabled = on => { const st = G.Save.settings(); st.noTut = !on; G.Save.saveSettings(st); };
  // start(id, force): every tour runs once per game (save); "Show the tour again" in How to play forces it
  Tut.start = function (id, force) {
    if (!force && !Tut.enabled()) return false;
    const S = G.S;
    if (!force && S) { S.tutSeen = S.tutSeen || {}; if (S.tutSeen[id]) return false; S.tutSeen[id] = true; }
    Tut.cur = { id, steps: TOURS[id](), i: 0 };
    setTimeout(Tut.show, 60);
    return true;
  };
  Tut.close = function () {
    document.querySelectorAll('.tut-spot').forEach(e => e.classList.remove('tut-spot'));
    const c = document.getElementById('tutcard'); if (c) c.remove();
    Tut.cur = null;
  };
  Tut.show = function () {
    const t = Tut.cur; if (!t) return;
    document.querySelectorAll('.tut-spot').forEach(e => e.classList.remove('tut-spot'));
    const st = t.steps[t.i];
    if (st.screen && UI.screen !== st.screen && !(G.S && G.S.event)) { UI.go(st.screen); }
    let card = document.getElementById('tutcard');
    if (!card) { card = document.createElement('div'); card.id = 'tutcard'; card.className = 'tut-card'; document.body.appendChild(card); }
    card.innerHTML = G.UI.era('<div class="row"><span class="tico">' + ic(st.icon || 'info', 22) + '</span><h3>' + h(st.title) + '</h3><span class="sp"></span><div class="tut-dots">' + t.steps.map((x, k) => '<i class="' + (k === t.i ? 'on' : '') + '"></i>').join('') + '</div></div>' +
      (st.body ? '<div class="sm muted">' + st.body + '</div>' : '') + (st.diagram || '') + (st.points ? '<ul class="sm">' + st.points.map(p => '<li>' + p + '</li>').join('') + '</ul>' : '') +
      '<div class="row mt"><label class="row xs muted"><input type="checkbox" data-chg="tutOff" ' + (Tut.enabled() ? '' : 'checked') + '> Don\'t show tutorials</label><span class="sp"></span>' +
      (t.i ? '<button class="btn sm" data-act="tutBack">Back</button>' : '<button class="btn sm ghost" data-act="tutSkip">Skip</button>') +
      '<button class="btn sm primary" data-act="tutNext">' + (t.i === t.steps.length - 1 ? 'Done' : 'Next') + '</button></div>');
    const el = st.sel ? document.querySelector(st.sel) : null;
    if (el) {
      el.classList.add('tut-spot');
      const r = el.getBoundingClientRect(), W = window.innerWidth, Hh = window.innerHeight, cw = Math.min(380, W - 32);
      let x = r.right + 14, y = r.top;
      if (x + cw > W - 16) { x = Math.max(16, Math.min(W - cw - 16, r.left)); y = r.bottom + 12; }
      card.style.left = x + 'px'; card.style.top = Math.max(16, Math.min(Hh - card.offsetHeight - 16, y)) + 'px'; card.style.transform = '';
    } else { card.style.left = '50%'; card.style.top = '50%'; card.style.transform = 'translate(-50%, -50%)'; }
  };
  UI.A.tutNext = () => { const t = Tut.cur; if (!t) return; if (t.i >= t.steps.length - 1) return Tut.close(); t.i++; Tut.show(); };
  UI.A.tutBack = () => { const t = Tut.cur; if (!t || !t.i) return; t.i--; Tut.show(); };
  UI.A.tutSkip = () => Tut.close();
  UI.A.tutOff = v => { Tut.setEnabled(!v); if (v) { UI.toast('Tutorials off. Turn them back on in ☰ → Settings or How to play.'); Tut.close(); } };
  // re-place the card after each render (screens change under it)
  const baseRender = UI.render;
  UI.render = function () { baseRender.apply(UI, arguments); if (Tut.cur) setTimeout(Tut.show, 0); };
  window.addEventListener('resize', () => { if (Tut.cur) Tut.show(); });

  // hooks: kickoff → season tour; first event; first match
  UI.A.kickoffDone = () => { UI.closeModal(); UI.go('hq'); Tut.start('season'); };
  const baseGo = UI.go;
  UI.go = function (screen, p) {
    baseGo(screen, p);
    if (!G.S || Tut.cur) return;
    if (screen === 'event' && G.S.event && G.S.event.kind !== 'einstein') Tut.start('event');
    if (screen === 'prematch') Tut.start('match');
  };

  // =====================================================================
  // How to play: categories with short, icon-led sections
  // =====================================================================
  const CATS = [
    { id: 'basics', icon: 'hq', name: 'Basics', desc: 'Turns, goals and the season loop', secs: [
      { icon: 'play', t: 'The loop', d: flow([['calendar', 'Offseason (months)'], ['bolt', 'Kickoff'], ['design', 'Build weeks 1–7'], ['event', 'Competition weeks 1–7'], ['trophy', 'Championship'], ['history', 'Review']]), li: ['Each <b>Continue</b> is one week in season, one month in the offseason.', 'Build week 7 is <b>Week 0</b> (scrimmage week). Competition week 7 has no regionals: a rest week before the Championship (for district teams it is District Championship week).', 'A career runs from the year you start in to 2026, one game a year. What changes from year to year is in <b>The decade</b> guide.'] },
      { icon: 'trophy', t: 'Goals and Program Support', li: ['At Kickoff the school sets three goals (minimum, target, stretch). The higher your reputation, the more they ask for: the list gets harder at 35, 55 and 75.', 'Meeting them raises <b>Program Support</b>; missing them lowers it. At 0 the program is cut (unless No-fail is on).', 'A district team gets district goals: reach the District Championship, finish in the district\'s top ten.', 'Program Support also decides how much workshop space the school gives you, and a season in which it rises brings free renovations or an upgrade grant (Workshop guide).', '<b>Reputation</b> brings sponsors, recruits and scrimmage invitations. It is earned slowly: a gain counts for less the higher it already is, and losses count in full.'] },
      { icon: 'inbox', t: 'Inbox', li: ['At least one news item and one to three chatter posts every turn.', 'Some messages take a <b>reply</b> (optional): small effects like reputation, spare parts or extra practice. Reply in the turn it arrives (a week in season, a month in the offseason) or the offer lapses.', '<b>Not everything gets a pop-up.</b> What the vendors, the rule makers and the second-hand market are about to do is usually talked about here first, as an ordinary message among the news and the chatter. Nothing marks those messages out: it pays to read the Inbox.', 'In season a <b>stock alert</b> warns that a part will be out of stock next week. Order it from the message that turn, or do without it for a week.'] }
    ] },
    { id: 'decade', icon: 'history', name: 'The decade', desc: '2016 to 2026: eras, the lost season, districts', secs: [
      { icon: 'calendar', t: 'Ten seasons', li: ['A career starts in the year you pick and ends after the 2026 season: ten seasons from 2016. There is no 2021 season.',
        'In real order every year plays its own game. In random order the games are shuffled, but everything else (vendors, rules, prices, mechanism kits, the lost season, districts) still follows the calendar year.',
        'One exception: FIRST STRONGHOLD allows tank drives only, so random order draws it only in 2016 or 2017, before anyone drives on swerve. A career from 2016 always plays it in one of its first two seasons; a career from 2018 on never does.',
        'Team numbers follow the year, as in FRC: a career from 2016 starts with teams numbered up to about 5,750, and each season\'s rookies take the next numbers (about 11,000 by 2026).',
        'Money is shown in the dollars of the current year: prices, fees and budgets rise a little every season.',
        'Big changes arrive as pop-ups and stay in the Inbox. Talk of them often reaches the Inbox earlier, with no pop-up, for those who read it. A career that starts later gets one letter, "FRC in" that year, with the state of the art.',
        'History keeps a picture of every season\'s robot. Name a robot in the Garage.'] },
      { icon: 'chip', t: 'Technology by year', li: ['<b>Motors</b>: brushed until Lumen launches the first brushless motor before the 2019 season. Sterling Motion, the premium vendor of 2016 to 2019, has no answer and closes; Apex Motion takes its place from 2020.',
        '<b>Swerve</b>: nobody sells modules before 2020. A team-built swerve needs a CNC Router or a Lathe, takes twice the build hours (one and a half times from 2018) and is fragile. From 2020 modules are sold, and swerve becomes the standard at the top.',
        '<b>Vision</b>: home-made until Lanternworks sells the Lantern 1 camera and a network switch for the 2018 season (before that, Level 1 costs twice the hours and Level 2 is out of reach). From 2023 the field has AprilTags: vision reaches higher and also helps autonomous, and Lanternworks sells the Lantern 2 camera and the Spark ML accelerator.',
        '<b>Gearboxes</b>: until 2016 mechanisms run on gearboxes the teams make themselves. From the 2017 season Sterling and Lumen sell planetary gearboxes (Apex takes over Sterling\'s line in 2020), and a low-profile one comes in every Kit of Parts.',
        '<b>Pneumatics and servos</b>: a pneumatics kit saves 25% of intake, manipulator and end effector build hours in 2016, 20% from 2020, 10% from 2023 and 5% from 2024, as motors take over. From the 2023 season a servo actuator kit does the same job better: 15%, then 20% from 2024.',
        '<b>Pits</b>: from the 2018 season the best teams roll in a Super pit (Workshop guide).',
        '<b>Drivetrains</b>: before swerve the strong teams drive West Coast, on two drive sets from a vendor. Sterling sells them until it closes. Lumen stops making them when it launches its own swerve module and sells the last stock through the 2022 season; Apex makes none. A West Coast drive also runs on two COTS Drive gearboxes, at lower performance: from 2023 that, or the sets you already own, is what there is. Swerve modules are sold by Apex from 2020 and by Lumen from 2022.',
        '<b>Mechanism kits</b>: until August 2021 only elevator, shooter and turret kits are sold. The lost year\'s catalogues add arm, intake, indexer, climber and gripper kits, and GridTube frame stock that every mechanical build can use.'] },
      { icon: 'box', t: 'Stop Build Day (2016–2019)', li: ['After build season the competition robot goes in a bag and may only be touched at events. With two robots that both run, you choose which one goes in the bag: it becomes the competition robot. In the Garage the bagged robot is greyed out, and neither robot can change role until the season ends.',
        'A scrimmage invitation can then only be taken up with a real second robot (a test chassis is not enough); without one the team declines.', 'Development goes on: a new mechanism, an upgrade, hardening or lightweighting finished during competition season is <b>packed</b> (Garage) and fitted in the pits with <b>Install Upgrade</b> on practice day at your next event. Until then the robot competes as it was bagged.', 'Only the newest version of a subsystem, or a unit identical to the one in the bag, can be packed: older units stay in storage. Install Upgrade fits the newest packed unit, and whatever it fits comes back to full condition.', 'Hardware projects for it run at half speed, and the drive team cannot practise at home.',
        'A second robot carries the work: with one running there is no slowdown at all, and the drivers practise on it.', 'District teams get six hours with the robot before each event: packed parts go on then, without using a practice block, and part of the lost speed comes back. Software and research are not affected.', 'The rule ends with the 2019 season.'] },
      { icon: 'incident', t: 'The lost season', li: ['Right after the 2020 Championship everything stops. The 2021 season is cancelled and the calendar jumps to June 2021.',
        '<b>This is the game\'s own timeline.</b> In reality the 2020 season was stopped in March 2020, part-way through its competition weeks, and its Championships were never held; the 2021 season was played from home, as remote challenges. The game lets 2020 finish and takes the whole of 2021 instead.',
        'Know-how fades by ' + Math.round(D.PANDEMIC.know * 100) + '%, students lose ' + Math.round(D.PANDEMIC.skill * 100) + '% of their skills, two senior classes graduate, and mentors and sponsors may leave. About a fifth of all teams fold.',
        'You choose <b>two programs</b> for the year at home: remote training (know-how), a skills challenge (student skills), community response (reputation, needs a 3D printer) or keeping the sponsors close.',
        'The 2021 offseason events are played with the 2020 robot. In 2022 the school is patient: missed goals cost half as much Program Support.'] },
      { icon: 'trophy', t: 'Playoffs and Championships by year', li: ['Events: single elimination (each series best of three) through 2022, double elimination from 2023.',
        'Championship: one in 2016 (eight divisions, a bracket on Einstein). Two from 2017 to 2020 (Houston, and St. Louis or Detroit), six divisions each and a round robin on Einstein before a best-of-three final. One again from 2022: six divisions and a round robin that year, eight divisions and double elimination from 2023.',
        'Regional teams: wildcards through 2024, the Regional Pool from 2025 (Calendar & events guide). With two Championships every district sends about one and a half times as many teams.', '2017 only: the two winning alliances meet in July at the Festival of Champions, a best of five. If you won Einstein you play in it: the trip is paid for and it cannot be skipped. Every other team can watch the series on a livestream that month, match by match on the field; watching is optional and free, and nothing is at stake.',
        'Until 2022 the Impact Award is called the Chairman\'s Award. It is the same award under its old name.'] },
      { icon: 'event', t: 'Districts', li: ['Pick a district as your home when you start, or join one when it forms in your area: the Mesa District in 2019 and the Sierra District in 2026 (a pop-up the July before asks you). Both models run side by side all career long.',
        'One registration fee covers <b>two district events</b>; a third is ' + U.money(D.FEES.extraDistrict) + ' and earns no points. Events are local, two days long, with about 36 teams and 12 qualification matches.',
        'Every event gives <b>district points</b>: qualification rank (22 down to 4), alliance selection (16 down to 1), playoffs, judged awards. Rookies add 10 once, second-year teams 5.',
        'After week 5 the top of the list plays the <b>District Championship</b> in week 7 (' + U.money(D.FEES.dcmp) + '), where points count three times. Then the district fills its Championship places: award winners and the winning alliance first, then the points list.',
        'The World page shows the district standings (district teams), every event\'s results, a map and season scouting of every team. The world grows as the real one did: more teams, more districts and fewer regionals every few years.'] }
    ] },
    { id: 'design', icon: 'design', name: 'Design & hours', desc: 'Concepts, projects, extra hours, fatigue', secs: [
      { icon: 'design', t: 'Concepts and projects', li: ['Pick a <b>concept</b> for each subsystem at Kickoff, then run <b>upgrades</b> with a focus stat and an effort level.', '<b>Effort</b> trades hours for the result. <b>Rush</b>: 60% of the hours, a weaker result, a risk of hidden faults, and 15% more materials (scrapped parts, overnight shipping). <b>Thorough</b>: 140% of the hours, a better and more reliable result, and 10% less material. Extra hours (below) add to any of the three.', 'The first one of a new concept or version is a <b>prototype</b> (+10% materials) and goes on the competition robot.', 'Each project absorbs up to 80 h a week (±25% by priority). Project slots come from mentors and facilities; fabrication (copies) and program projects (the Impact and Woodie Flowers essays, the Knowledge Base) need none.', 'A project started this turn can be <b>undone</b> for everything it cost until you press Continue: builds, upgrades, research, copies, a test chassis. After that it can only be cancelled, for part of its materials.', 'Keep the robot under <b>125 lb</b>.'] },
      { icon: 'arm', t: 'End effector, lift and intake', li: ['In 2018, 2019, 2023 and 2025 the robot has an <b>End Effector</b>: the claw or gripper at the end of the lift, built on the <b>End Effectors</b> knowledge area. Its <b>Grip</b> decides how surely it takes, holds and lets go of a game piece: a poor one costs placements and a little time on every score, a developed one gives both back.', 'In those games the ground intake is <b>optional</b>. Without one the end effector collects the pieces itself, from the human player (and in 2018 off the floor): slower than a good intake, but it saves the weight, the hours and the money.', 'A robot needs both a lift and an end effector to score. From August 2021 a gripper kit speeds the build, and a pneumatics or servo kit helps too.'] },
      { icon: 'atom', t: 'Knowledge each concept needs', li: ['Each concept has <b>core areas</b> (★). A turret shooter is a flywheel shooter on a turret, so it needs both Turret and Flywheel Shooter knowledge.', 'Any core area at Level 0 on a complex concept means a first-time penalty. Build hours and ceilings use the average of the core areas.'] },
      { icon: 'trophy', t: 'Elite designs', li: ['Seven games have mechanisms marked <b>elite design</b>, at most one a subsystem: the hardest of its season, built by the best teams in the world. It costs the most hours and money, has the most to go wrong, and beats the next best by only a few percent. The team is never advised to build one: it is your call.',
        '<b>2016 Turret + hood shooter</b>: aims while the robot is still driving, and a blocker cannot push its aim off. Worth little in the open and a lot against a defender.',
        '<b>2019 Turreted elevator + wrist</b>: loads on one side and places on another without turning the chassis. A tank drive saves about half a second of lining up on every leg; a swerve or mecanum drive, which lines up quickly anyway, saves little.',
        '<b>2023 and 2025 Pivoting telescope</b>: a telescoping arm on a low pivot. It scores like the best lift of its year, <b>never tips</b>, balances a little better on the Charge Station (2023) and climbs the cage a little quicker and surer (2025).',
        '<b>2019 Triple Level 3 climber</b>: carries both partners onto HAB Level 3, 36 points from one climber. Both partners must be at the HAB in time, or it climbs alone (with one partner it would not balance). A failed lift can drop them, and bring the climber down as well: big when it works, risky when it does not.',
        '<b>2020 Full-width four-bar intake + revolver indexer</b>: fires the five cells it holds much faster, and the four-bar folds out of the way when it is hit, so the intake rarely jams or breaks.',
        '<b>2022 Dual-side intake</b> takes cargo from either end without turning round. <b>2022 Direct traversal climber</b>: quicker, surer and less likely to fall than a traversal climber, but it can only hang on Traversal.',
        '<b>2026 Linear slide intake</b>: packs the fuel down so the shooter is fed faster, and slides back when hit. <b>2026 Dye-rotor turret</b>: more fuel a second than a standard turret, and more consistent shots.',
        'Only the strongest teams in the world field them, so you meet them at the Championship more than anywhere else.'] },
      { icon: 'garage', t: 'Copies and fabrication', d: flow([['design', 'Design + prototype'], ['bolt', 'Build copy'], ['garage', 'Robot 2 or a spare']]), li: ['<b>Build copy</b> makes another unit of a finished design: about a quarter of the first build\'s hours and 60% of its materials, plus its own control system parts and kits.', 'Copies go to the robot that lacks the latest version (the second robot first), otherwise to storage as a spare.', 'Copies are <b>fabrication</b>: they use team hours but no project slot. The Garage\'s <b>test chassis</b> and <b>full copy</b> are shortcuts that start copies, nothing else.', 'A copy that cannot go on its robot for want of parts waits in storage, and the Inbox says which parts and how many (what each robot uses, what is on the shelf). Optional parts (planetary gearboxes, a network switch, an ML accelerator) never stop a copy.'] },
      { icon: 'bolt', t: 'Finish now cards', li: ['Each top-level facility gives one <b>Finish now</b> card a season: CNC Machining, 3D Printing and the Machine Shop one each for a hardware project, the Programming Station one for a software project (code, autos, vision).', 'A card finishes a project that is at least half done at once, extra hours included, at no cost and with no penalty. The button is on the project\'s row in the Design Office, and Active projects shows the cards left this season (e.g. hardware 2/3 · software 1/1).'] },
      { icon: 'clock', t: 'Extra hours', d: flow([['clock', 'Planned hours'], ['bolt', '+ extra hours'], ['check', 'Better result']]), li: ['Set <b>extra hours</b> (in steps of 1 h) on any project: they use hours that would sit idle.', '<b>Auto-fill extra hours</b> does it for you: it puts the turn\'s idle hours into extra hours on the projects already running, and starts no project. In season it fills the week to 90% and leaves the idle tenth that holds fatigue steady (a week already at 90% or more is left alone); in the offseason it fills the whole month. Tick <b>every turn</b> to have it done when you press Continue.', 'Quality rises with diminishing returns: doubling a project gets about 80% of the maximum bonus.', 'Builds start with better stats, upgrades gain more and add less weight, hardening goes further. You can\'t lighten anything below 40% of its design weight.'] },
      { icon: 'fatigue', t: 'Fatigue (in season)', li: ['Fatigue settles around <b>30</b>. Leaving about <b>10% of the week\'s hours idle</b> holds it there.', 'Busier weeks, <b>overtime</b> (+10) and <b>competition weeks</b> (+9) raise it; idle time and team nights lower it. The offseason resets it.', 'It only matters at events: tired teams have more <b>incidents</b> and less reliable <b>scouting</b>.'] },
      { icon: 'pfield', t: 'Testing hours', li: ['Testing hours come from a <b>test chassis or second robot</b> (Garage) and from a <b>Practice Field</b> (Workshop). A test chassis alone gives ' + D.CHASSIS_TEST_HOURS + ' h a week in the shop or parking lot. A Practice Field gives ' + D.EQUIP.find(e => e.id === 'pfield').fx.test.join(', ') + ' h by level, and a second robot adds up to ' + D.TEST_BOT_HOURS + ' more (a bare test chassis half of that).',
        'Split them between <b>development testing</b> (projects finish faster and come out better) and <b>driver practice</b> (skills, confidence and familiarity with the robot they practice on).',
        'On a test chassis without a Practice Field, development testing only works for robot code, autos, vision and drivetrain projects (at half the cost), and driver practice counts ' + Math.round(D.CHASSIS_ELEM * 100) + '%.',
        'On a Practice Field, driver practice needs this game\'s field elements (Inventory → Game elements) for full value.',
        'With a second robot running, the same hours also build defense drills and the electrical shakedown (Garage guide).'] },
      { icon: 'incident', t: 'The state of the art moves', li: ['From your second season, each offseason opens with two <b>rule or vendor changes</b> for next season, and one month between July and September brings three <b>new designs spotted online</b>.', 'Each makes one knowledge area partly outdated: −25% XP for rule and vendor changes, −15% for new designs (banked XP far above the top level doesn\'t protect it).', 'A mentor who specializes in the area halves the loss. Research wins it back.', 'Know-how at <b>Level 4 or 5</b> is tuned to the way things were, so it adapts worst: a change costs it half as much again and always takes one level, with or without a specialist mentor (the mentor softens how far it falls within that level).'] },
      { icon: 'know', t: 'Tech Knowledge', li: ['Building and competing with a concept earns knowledge; research earns it directly.', 'Each level gives concepts that use the area +3 on their stat ceilings, 6% fewer build hours, +4 starting reliability and 5% better upgrades, in every later game.', 'An area you did not use in a season loses 20% of its XP as students graduate (10% with a Knowledge Base), unless a mentor specializes in it.', 'The <b>Knowledge Base</b> is not built once and forgotten: it covers the season it was built or last updated for. Every year after that it needs a ' + D.KB_UPKEEP_HOURS + '-hour update (Design Office); out of date, it protects nothing.'] }
    ] },
    { id: 'garage', icon: 'garage', name: 'Garage & two robots', desc: 'Robot 1 and 2, familiarity, storage, spares', secs: [
      { icon: 'garage', t: 'Two robots', li: ['Every season you have <b>Robot 1</b> and <b>Robot 2</b>. Either can be the <b>competition robot</b>: it gets the best control system parts and goes to events.', 'Fit built subsystems to either robot in the Garage, swap them between robots, or take them off into storage.', 'A second robot gives up to +6 testing hours a week (with a Practice Field), up to 25% more effective driver practice on it (the competition robot can be worked on meanwhile), better tuning at events, and its identical subsystems are spares at events. These scale with how many of the competition robot\'s subsystems it copies: a bare chassis gives little.', 'It costs a lot: a second control system plus copies of every subsystem. Usually only well-funded teams with big inventories can justify it, rarely in a first season.', '<b>Build a full copy</b> (Garage) starts one Build copy for each finished subsystem the second robot lacks, all at once, or none if the parts or money fall short; the message lists what is missing.', 'A real second robot (one that carries mechanisms, not only a test chassis) also does the team\'s sponsor demos and shows, so the competition robot keeps its condition, and it can go to a scrimmage when the competition robot is in the bag.'] },
      { icon: 'clock', t: 'Test chassis', li: ['A <b>test chassis</b> is the second robot with only a drivetrain. The Garage shortcut builds a copy of your drivetrain for it, the same as Build copy; before the drivetrain is designed (or to drive another way) it can be a basic Kitbot Tank, Mecanum or West Coast Drive at its base stats. No project slot.', 'Without a Practice Field it gives ' + G.Data.CHASSIS_TEST_HOURS + ' testing hours a week in the shop or parking lot: development testing for robot code, autos, vision and drivetrain projects (half the usual cost), and driver practice (at ' + Math.round(G.Data.CHASSIS_ELEM * 100) + '% quality). With a Practice Field it counts as half a second robot.', 'Programmers and drivers start before the competition robot drives. Practising on a different drivetrain only partly carries over to the competition robot\'s.'] },
      { icon: 'shield', t: 'Second robot drills', li: ['With two robots running, driver practice includes <b>defense drills</b>: one robot plays defender. At 100% your drivers lose 35% less speed, cycle time and accuracy to a defender in matches. It resets at Kickoff.', 'In the bag years, drills stop once the competition robot is bagged: only one robot drives at home. What the drivers learned before Stop Build Day stays.', 'A second robot that drives like the competition robot (tank: Kitbot, West Coast; holonomic: Mecanum, Swerve) lets programmers test paths early: auto routines and auto upgrades develop 20% faster, plus Autonomous Pathing XP every week.', 'Any second robot that runs in season (a test chassis is enough) is also a full control system to wire and debug early. The <b>electrical shakedown</b> grows with the testing hours you run (30 h for 100%): the competition robot then has 40% fewer brownouts and comms dropouts at its first event, 25% at the second and 10% after that. It adds Electrical & Reliability XP every week and resets at Kickoff.'] },
      { icon: 'team', t: 'Driver familiarity', d: flow([['bolt', 'New mechanism about 35%'], ['play', 'Practice and matches'], ['check', 'Up to 100%']]), li: ['The drive team knows each subsystem they have driven. In matches a subsystem gives 85–100% of its stats depending on familiarity.', 'A new version of the same mechanism costs a few percent; switching concept costs 20–65% (a dumper to a turret, or tank to swerve, is a big change).', 'Weekly shop driving, driver practice, event practice blocks and matches win it back. Choose which robot the drivers practice on: practicing on an older robot keeps them familiar with the old parts.'] },
      { icon: 'box', t: 'Storage and spares', li: ['Up to 2 built units of each subsystem fit in storage. When a build would overflow it, the oldest is taken apart (the build quote warns you).', '<b>Take apart</b> any stored unit for spare parts; its mechanism kits go back on the shelf. The storage setting <b>Take apart old versions automatically</b> does it for every unit that is neither the latest design nor identical to the competition robot\'s, whenever a project finishes and at the end of each turn.', 'A spare identical to the competition robot\'s (same concept and version), in storage or on the other robot, goes to events: swap it in between matches to restore that subsystem to 100%.', '<b>Event spares</b>: at most ' + (G.Data.STORE_MAX + 1) + ' of each subsystem (' + G.Data.STORE_MAX + ' in storage and the other robot\'s). The Design Office shows storage and event spares for each subsystem, the Garage the event spares of all of them; once storage holds ' + G.Data.STORE_MAX + ' copies of the latest version and both robots have it, Build copy is refused.'] }
    ] },
    { id: 'parts', icon: 'parts', name: 'Inventory', desc: 'Vendors, stock, wear, kits, game elements', secs: [
      { icon: 'chip', t: 'Two control system vendors', li: ['The premium vendor (<b>Sterling Motion</b> until it closed in 2019, <b>Apex Motion</b> from 2020): top performance, premium prices. <b>Lumen Robotics</b>: dependable and cheaper. Sterling and Apex parts fit together, so they never count as mixed. Drivetrain parts and planetary gearboxes are not part of the control system and never count as mixed either.', 'The <b>control system</b> (motors, encoders, control hubs) comes from one of them (Inventory, Control system tab), and so do <b>West Coast drive sets</b> (2 per drive), <b>swerve modules</b> (4 per drive, once somebody sells them) and <b>planetary gearboxes</b>.', '<b>Mixing</b> both on the competition robot: hardware and software projects take 10% longer, and the robot loses a little reliability and speed. Use "Premium first" or "Lumen first" to keep one system.', 'Every autumn at least one vendor, usually both, holds a launch event 1–4 months before Kickoff, with one to three new products (a pop-up and an inbox post). The previous version stays on sale through the next season. Over ten seasons a product line reaches version IV or V.'] },
      { icon: 'gear', t: 'What a drive runs on', li: ['Three kinds of part, from the lowest performance to the best. The <b>Kit drivetrain</b> (Kit of Parts, 2 free at every Kickoff) fits the kit chassis only.', '<b>Drive gearboxes</b> (Subsystem COTS) are the middle step: 2 of them make a kit chassis faster and stronger (+' + D.DRIVE_UP.speed + ' Speed, +' + D.DRIVE_UP.push + ' Pushing on its ceilings), a mecanum drive needs 4, and 2 carry a West Coast drive when you have no vendor sets for it.', '<b>Vendor drive sets</b> are what a West Coast drive is meant to run on: its Speed and Pushing ceilings rise with the quality of the sets, and on Drive gearboxes they sit below even the cheapest set.', 'The better part is used whenever the shelf has it, the competition robot first. The concept list and the Inventory show what each drive is running on.'] },
      { icon: 'trophy', t: 'Vendor loyalty', li: ['Each vendor keeps a <b>loyalty level</b> for your team: Customer, Loyal Team, Preferred Team, Partner Team, Flagship Team. The premium catalogue\'s level carries over from Sterling to Apex.',
        'A season is worth ' + D.LOYALTY.robot + ' points with a vendor when your competition robot runs on its control system at your events (' + Math.round(D.LOYALTY.full * 100) + '% of them is enough; kit parts and the other vendor\'s parts count against it), and up to ' + D.LOYALTY.buy + ' more for ordering its parts that year (' + U.money(D.LOYALTY.buyFull) + ' for all of it). "Premium first" or "Lumen first" on the Your robots tab keeps the robot on one vendor.',
        'Levels come at ' + D.LOYALTY.levels.join(', ') + ' points: a team that stays with one vendor reaches three of them in a ten-season career.',
        'At each new level the vendor sends a <b>loyalty sponsorship</b> in September, as a pop-up. Choose one: <b>free parts</b> delivered at Kickoff in the newest version, a <b>voucher</b> that pays first when you buy from that vendor and lasts through the next season, or a <b>limited-time offer</b> of ' + Math.round(D.LOYALTY.sale[1] * 100) + '% to ' + Math.round(D.LOYALTY.sale[4] * 100) + '% off everything from that vendor until Kickoff. Higher levels give more.',
        'From level 1 your in-season orders ship first: +' + Math.round(D.LOYALTY.stock * 100) + '% chance per level that a part from that vendor is in stock.',
        'The Control system tab shows each vendor\'s level, your points, and any voucher or sale you hold.'] },
      { icon: 'box', t: 'Kit of Parts and stock', d: flow([['truck', 'Offseason: everything in stock'], ['bolt', 'Kickoff: free kit'], ['incident', 'In season: popular parts sell out']]), li: ['Every team gets a free kit at every Kickoff: 4 brushed motors, 2 low-profile encoders, 2 kit drivetrain sets, from 2017 2 low-profile planetary gearboxes, and game pieces. Only rookies get a control hub, in a bigger first-season kit; veteran teams start with one leftover kit hub.', 'Every Kickoff also brings <b>KOP mechanism vouchers</b>: 2 in a rookie\'s first season, 1 in every other. Each one pays for a KOP subsystem kit (gripper, intake, shooter or lift) in Subsystem COTS until the next Kickoff.', 'In the offseason everything is in stock. In season a part is often <b>sold out</b> for the week, and how often depends on how many teams want it: a brand-new technology (the first brushless motor, the first swerve modules) is hard to get, the part it outclasses sits on the shelf, and a mechanism kit goes as fast as this game\'s robots use it. Stock up before Kickoff.', 'A <b>stock alert</b> in the Inbox names a part that will be out of stock next week; you can order it from the message that turn.', 'More <b>Kit of Parts</b> control system parts (brushed motors, low-profile encoders, a basic hub, kit drivetrain sets) can be bought any time: very cheap and never sold out, but much slower. Next to vendor parts they cost 5% more project hours and a little performance. They can\'t be resold.'] },
      { icon: 'gear', t: 'Planetary gearboxes', li: ['From the 2017 season both vendors sell planetary gearboxes for mechanism motors (not the drivetrain): one gearbox per motor. They are optional.', 'The more of the competition robot\'s mechanism motors have one, and the better they are, the more reliable the robot: mechanisms break down less. The Your robots tab shows how many are covered.', 'They are not part of the control system: Sterling (later Apex) and Lumen gearboxes mix freely with either vendor\'s motors. The <b>KOP low-profile gearbox</b> only fits KOP motors; two come in every Kickoff kit (four in a rookie kit).'] },
      { icon: 'camera', t: 'Lanternworks: vision hardware', li: ['<b>Lanternworks</b> sells the vision hardware, in its own catalogue under Subsystem COTS, from the autumn of 2017. Vision Level 1 needs one camera, Level 2 two.', '<b>Lantern 1</b> (from 2018) tracks reflective tape. <b>Lantern 2</b> (from 2023) reads AprilTags and replaces it in the store; a Lantern 1 still works, but with tags on the field it aims less well. A better camera improves accuracy and vision.', 'The <b>Lantern Link network switch</b> (optional, one per robot) puts the camera, controller and radio on one network: fewer comms dropouts in matches and a little better vision.', 'The <b>Lantern Spark ML accelerator</b> (optional, from 2023, one per robot with vision) runs object detection on the robot: it finds game pieces and lines up its shots better.'] },
      { icon: 'air', t: 'Pneumatics and servo kits', li: ['A <b>pneumatics kit</b> or a <b>servo actuator kit</b> speeds up intake, manipulator, end effector, climber and adjustable-hood shooter builds. With both, the better one counts.', 'Pneumatics save the most in the brushed-motor years and less every year after brushless motors arrive (25% in 2016, 5% from 2024). Servo kits are sold from May 2022 and save 15% from the 2023 season, 20% from 2024.'] },
      { icon: 'garage', t: 'What builds use', li: ['A swerve drive uses 4 modules, 8 motors and 4 encoders; tank drives 4–6 motors and 2 gearboxes; most mechanisms 1–3 motors (plus a planetary gearbox each, if you want them).', 'Each robot needs one control hub; a <b>second robot</b> needs its own control system.', 'Parts are reusable: the best ones go on the competition robot, the rest on the other robot.'] },
      { icon: 'spare', t: 'Wear and slots', li: ['Parts wear in matches and practice. Worn parts barely slow the robot but fail more often.', 'Each part type has a slot limit; buying more replaces your most worn parts. Replaced parts above 60% condition are sold for you, the rest are recycled.'] },
      { icon: 'money', t: 'Selling parts', li: ['Sell parts you no longer need in <b>Inventory → Sell</b>: about 55% of today\'s list price at full condition, less as they wear.', 'Only parts above 60% condition can be sold. Kit parts can\'t, and you can\'t sell below what your robots need.', 'Handy when switching vendors: sell the old set while it still has value.', 'The <b>second-hand market follows the news</b>. A part that has been overtaken sells for less from the day its replacement goes on sale: an older version, a brushed motor once brushless ones exist, anything from a vendor that closed, West Coast drive sets once swerve modules are sold, a Lantern 1 once Lantern 2 is out, a pneumatics kit as motors take over. The Sell tab shows each markdown and the reason.'] },
      { icon: 'elevator', t: 'Mechanism kits (optional)', li: ['Each concept can use a set of COTS kits: a turret shooter takes a turret kit and a shooter kit, a traversal climber up to 4 climber kits, a tall elevator 2 stage kits.', 'A full set makes the build 28% faster, uses 25% less material and removes the first-build penalty; a partial set gives part of that. Copies use kits too.', 'Kits stay in the subsystem they were built into. Take a stored subsystem apart to get them back. They wear with use, and worn kits help less (down to half). Without kits, the team fabricates its own.', '<b>GridTube frame stock</b> (from August 2021) is box tube and gussets on one hole pattern. Every mechanical build can use 1 to 3 bundles by size, the drivetrain included: with all of them, ' + Math.round(D.FRAME_HOURS * 100) + '% fewer hours and ' + Math.round(D.FRAME_COST * 100) + '% less material, on top of the kits. The shelf holds ' + D.PART_CAT.kFrame.max + '.', 'Before August 2021 only elevator, shooter and turret kits exist; arm, intake, indexer, climber and gripper kits arrive with the lost year\'s catalogues. The Kickoff pop-up names the kits this game could use that are not sold yet. Kits follow the calendar, not the game: in random order a newer game drawn before 2021 is built without them, and an older game drawn later gets them.', '<b>Kit of Parts subsystem kits</b> (KOP gripper, intake, shooter and lift) are sold in every year, cheap and never out of stock. Each helps only the simplest concept of a subsystem: ' + Math.round(D.KOP_KIT_HOURS * 100) + '% fewer hours and ' + Math.round(D.KOP_KIT_COST * 100) + '% less material. A build that uses a COTS kit does not take one as well.'] },
      { icon: 'elements', t: 'Game elements', li: ['Without a Practice Field the kit game pieces are all you need. With one, sets fill it up to its size: Level 1 fits a quarter set, Level 2 a half set, Level 3 a full set.', 'Preordered sets show as <b>pending</b> right away and arrive at Kickoff.', 'They wear with driver practice, and worn sets count for less. Store up to two fields\' worth: a spare set bought before the season guards against in-season shortages.', 'In season they often sell out: <b>preorder</b> next season\'s elements in the offseason (they arrive at Kickoff). A pop-up and an Inbox message in November remind you if nothing is on order.'] },
      { icon: 'battery', t: 'Spare parts and batteries', li: ['Spare parts fix the robot at home and in the pits. They are cleared out at each Kickoff.', '<b>Auto-restock</b> (on by default) keeps enough spares for driver practice and home repairs every turn, and buys what the next event needs.', 'One spare restores about ' + D.SPARE_COND_PER_UNIT + ' condition points; at events they cost double.', 'Only the battery used in a match wears (about 1% a match); batteries also age slowly on the shelf. New ones fill empty slots, then replace the most worn. A Battery Station at level 2 holds 20.'] }
    ] },
    { id: 'workshop', icon: 'workshop', name: 'Workshop', desc: 'Facilities, the trailer, incidents', secs: [
      { icon: 'workshop', t: 'Workshop space', li: ['Every facility level takes floor space in square feet; the trailer parks outside. The bar at the top of the Workshop shows what is used, what is free and what the school has not given you yet.', 'Three levels: the robotics classroom (2,550 sq ft), the technology wing (3,850) and a robotics center (5,100, which fits everything). A rookie starts in the classroom, established and powerhouse teams in the technology wing. At a season review the school moves you up when Program Support has reached 80 (wing) or 90 (center). Room is never taken back.', 'When support rises by 6 or more in a season, the board renovates your worn facilities for free; at +12 (and support 60+) it adds a grant for one upgrade of your choice up to ' + U.money(D.BOARD.cap) + '. When nothing in the workshop can be upgraded with it (every facility at its top level, too dear or out of room), the grant comes as ' + U.money(D.BOARD.cash) + ' in cash instead.', 'A satisfied sponsor may donate a facility level that fits its business, if you have the room: the higher its satisfaction above 60, the likelier. With every sponsor slot filled and no sponsor activity skipped, expect about one donation a year.'] },
      { icon: 'ebench', t: 'Electronics, welding, meeting room and FTC space', li: ['<b>Electronics Workbench</b>: fewer brownouts and comms dropouts in matches; motors and electronics wear more slowly.', '<b>Welding Station</b>: hardening and lightweighting take fewer hours and do more; new builds are more reliable.', '<b>Team Meeting Room</b>: outreach counts for more and adds to your Impact presentation score.', '<b>FTC Team Space</b>: run one to three FTC teams of your own (Team page, Feeder programs). Each takes a program slot, costs $300 a year and counts 1.8× for recruit quality.'] },
      { icon: 'cnc', t: 'Facilities', li: ['3D printing, CNC, machine shop and programming station cut hours and can add project slots; at their top level each also gives a <b>Finish now</b> card every season (Design & hours guide). The Battery Station and Pit Setup help between matches, and the Practice Field adds testing hours.', 'They wear down, mostly in the build and competition weeks (a whole offseason month costs about half of what one build week does), and a worn facility works at 40–100% of its effect. Below 35% condition it also loses its project slot until renovated. Upkeep is charged per level at Kickoff.', 'Some unlock new outreach and fundraising activities.', '<b>Downgrade</b> (or Remove, at level 1) gives a level back to make room. Half that level\'s price comes back at full condition, less as it wears, and nothing for a level that was donated or paid by a grant. Buying it again costs the full price.'] },
      { icon: 'pitcart', t: 'Super pit', li: ['The top level of Pit Setup, from the 2018 season (on sale from the autumn of 2017): the whole pit in road cases. It takes no more room than a full pit setup.', 'Before any match the crew fully repairs <b>one subsystem of your choice</b> (pre-match page), with spare parts as usual. When you simulate the qualification matches it repairs whichever subsystem is in the worst shape, before every match.', 'Its screens help the strategy team: scouting estimates at events are sharper and the team reads the game a little faster.'] },
      { icon: 'trailer', t: 'Team trailer', li: ['Far events become a long drive instead of a flight: 15% cheaper and no air-freight damage.', 'Robot demos for sponsors wear the robot less; robot outreach counts 20% more; unlocks the Trailer roadshow.'] },
      { icon: 'incident', t: 'Shop incidents', li: ['Now and then something breaks or goes wrong in the shop: pick how to handle it.'] }
    ] },
    { id: 'team', icon: 'team', name: 'Team & outreach', desc: 'Drive team, mentors, activities, Impact', secs: [
      { icon: 'team', t: 'Students and the drive team', li: ['The drive team has five seats: driver, operator, human player, coach and an optional technician. Each uses different skills (see Drive team roles below); they improve with matches and practice.', 'Seniors graduate in June; new students join in September, more of them with reputation, outreach and feeder programs. A team is full at ' + D.STUDENT_CAP + ' students: further applicants go on a waiting list.'] },
      { icon: 'mentors', t: 'Mentors', li: ['Design and fabrication mentors add project slots; each role has its own benefits. A specialist (in one knowledge area, End Effectors included) halves what rule changes and new designs take from that area.', 'The mentor market refreshes every August. After that, <b>Search for more mentors</b> brings a new list of candidates for a small fee, twice at most before Kickoff.'] },
      { icon: 'outreach', t: 'Outreach and fundraising', li: ['Up to 3 activities a week (12 a month in the offseason), each type once a week.', 'Repeating an activity <b>in the same month</b> pays less; it resets every month.', 'Facilities, sponsors, mentors and the trailer unlock more activities. The STEM summer camp is offseason only; the team pizza and movie night is for the season, when the team is tired.', '<b>Every turn</b> (Team page): All fundraising, All outreach or Mixed fills the free activity slots on its own when you press Continue, the best first and only what you can afford.'] },
      { icon: 'trophy', t: 'Impact Award', li: ['Needs a submission (Design Office) and a strong Impact rating built over several seasons of outreach.', 'The rating has five parts: this season\'s outreach (' + Math.round(G.Career.IMPACT_W.outreach * 100) + '%), your track record over three seasons (' + Math.round(G.Career.IMPACT_W.record * 100) + '%), Presentation (' + Math.round(G.Career.IMPACT_W.pitch * 100) + '%), feeder programs (' + Math.round(G.Career.IMPACT_W.programs * 100) + '%) and reputation (' + Math.round(G.Career.IMPACT_W.rep * 100) + '%). The Team page shows each one; hover a line for what moves it.', '<b>Presentation</b> is 60% of your Business mentor\'s skill, plus 60% of your two best presenters\' average Strategy and Awareness, plus a Team Meeting Room. Without a Business mentor it stays low whatever else you do.', 'Regional winners are judged again at the Championship for the <b>FIRST Impact Award</b>: six Finalists are named before Einstein Final 1 and the winner after it. Both earn a blue banner; the winner joins the Hall of Fame and is invited to every future Championship.', 'You don\'t have to play on Einstein to be there: a regional Impact winner that is out of the tournament watches the finals from the stands and hears the announcement on the field.'] },
      { icon: 'mentors', t: 'Woodie Flowers Award', li: ['The award for a mentor who leads, inspires, teaches and empowers through communication. Dr. William Murphy founded it in 1996 and named it after Woodie Flowers, the MIT engineering professor who brought Gracious Professionalism to FIRST and was its first recipient. It does not qualify the team for anything.',
        'Every season the students may write <b>one essay about one mentor</b> (Design Office, Program projects). The game picks the strongest nomination; you can choose another. Extra hours make a better essay.',
        'A mentor who has never won it is judged for the <b>Woodie Flowers Finalist Award</b>: a regional team\'s at its next regional, a district team\'s at its District Championship (district events have none). Each regional names one Finalist; each District Championship one, two or three from 2022 at the biggest districts. A mentor receives the Finalist award once.',
        'At the Championship there are no Finalists: one <b>Woodie Flowers Award</b> goes to one mentor, chosen from all of the season\'s Finalists and the past Finalists their teams re-nominate. To re-nominate a past Finalist, write the season\'s essay about them. Nobody receives it twice, and it is very hard to win.',
        'The essay rests on the mentor (skill, seasons with the team, years in FIRST, how many students they reach; a teacher by profession counts a little extra) and on the students who write it (the two best at Strategy and Awareness) and the hours they put in.',
        'A Finalist award brings +' + D.WFA.rep.wffa + ' reputation, the Award +' + D.WFA.rep.wfa + '. Each hangs a <b>blue banner</b> for the team (the Award\'s with the Championship honours), and shows on the mentor\'s row (Mentors) and under Mentor honours (History). A mentor who has received either never leaves the team on their own. The Award is presented on Einstein right after the FIRST Impact Award: a team whose mentor wins goes there to watch, qualified or not.',
        'Real winners include Glenn Lee of Team 359 (2017), Lucien Junkin of Team 118 (2020, a NASA chief engineer who had been a Finalist in 2005), Norman Morgan of Team 2468 (2024) and Debbie English of Team 4499 (2026).'] },
      { icon: 'team', t: 'Drive team roles', li: ['<b>Driver</b>: Driving (speed and line-up), Awareness (less time lost to defenders, fewer fouls), Composure.', '<b>Operator</b>: Mechanism skill (faster intake and scoring), Composure.', '<b>Human Player</b>: HP skill. In the games where the human player feeds the robot all match (2017, 2019, 2020, 2023, 2024, 2025) it sets how fast the robot is loaded: an expert crew needs about two thirds of the time an average one does, which is worth 5 to 10% of an alliance\'s score. An alliance uses its two best human players. In the others (2016, 2018, 2022, 2026) it hardly matters.', '<b>Coach</b>: Strategy (Coach Calls, reading the season\'s strategies). A student coaches when their Strategy beats the adult behind the glass.', '<b>Technician</b> (optional): Mechanism speeds up pit repairs, Composure catches pre-match mistakes such as wrong code or a loose bumper.', 'Skills grow by playing matches in a role and by driver practice. "Auto-pick best" fills all five seats.'] },
      { icon: 'sprout', t: 'Feeder programs', li: ['Up to 6 programs, $1,000 a year each (paid in September). They grow over three school years: 60%, 85%, then 100% strength.', 'Each September they bring extra students (more hours) and better recruits. A program\'s focus (Balanced, Drive team, Technical, Strategy, Outreach) trains the skills of the recruits who come from it.', 'Outreach programs bring the most students and count most toward Impact. Changing a focus costs a year of growth, except while the program is new.', 'With an <b>FTC Team Space</b> (Workshop) you can run up to three FTC teams of your own in those slots: ' + U.money(D.FTC_OWN.cost) + ' a year each, and they count ' + D.FTC_OWN.power + '× for recruit quality.'] }
    ] },
    { id: 'money', icon: 'finance', name: 'Money', desc: 'Sponsors, debt, the STEM fund', secs: [
      { icon: 'sponsor', t: 'Sponsors', li: ['The <b>Sponsor funding</b> card on the Finance page shows this season (base paid, bonuses reached and still possible) and next season (expected base and possible max bonus). A deal in its last season renews with a chance equal to its satisfaction at the season review.', 'Offers arrive in October. A title sponsor pays about three times a partner.', 'Offers grow a little with reputation and last season\'s results.', 'You hold one title sponsor, one grant and 4 partners (5 with a Business mentor). Signings made this turn can be undone until you press Continue; "Auto-pick best" fills the open slots.', 'From October to Kickoff, while the new offers are open, you can <b>end a sponsorship</b> to free its slot for a better offer. It costs reputation: 6 for a title sponsor, 3 for a partner, 2 for a grant, plus 1 for each further season the contract had to run.', '<b>Top programs</b> (powerhouse or very high reputation) attract sponsors who expect wins: miss a regional win or Championship spot and they cool off fast.', 'A satisfied sponsor sometimes <b>donates</b> a facility level that fits its business, if the workshop has room. The higher its satisfaction above ' + D.DONATION.sat + ', the likelier: about one donation a year with every slot filled and no sponsor activity skipped.'] },
      { icon: 'money', t: 'Debt', li: ['From Kickoff to the Championship you can spend into debt (down to −' + U.money(D.DEBT_LIMIT) + ').', 'The school clears it at the season review, at a cost in Program Support and reputation: the bigger the debt, the bigger the cost, and half as much again for each season in a row that ends in debt. A strong season can be worth it.', 'In the offseason you can only spend cash you have.'] },
      { icon: 'fund', t: 'STEM support fund', li: ['When the balance is under ' + U.money(D.STEM_FUND.below) + ', apply for up to ' + U.money(D.STEM_FUND.max) + ' (twice a program year). Each application costs ' + D.STEM_FUND.rep + ' reputation.'] }
    ] },
    { id: 'calendar', icon: 'calendar', name: 'Calendar & events', desc: 'Registration, withdrawing, skipping', secs: [
      { icon: 'calendar', t: 'Registration', li: ['Regional teams register for up to four regionals (weeks 1–6) from October. District teams register for the events of their own district: two for one fee, three at most (see The decade guide).',
        'Registration opens in October with a pop-up and an Inbox message. A career team must be registered for at least one event by the end of December: until it is, Continue stops there with a pop-up. A team that cannot pay a fee yet (only cash can be spent in the offseason), or has nothing open to it, is warned instead and may register after Kickoff.',
        '<b>Field strength</b> (★ to ★★★★★): how strong an event\'s field is. A stronger field is harder to win but teaches the team more: drive-team skills, the know-how from competing and the strategy read grow ×' + (1 - 2 * D.EVENT_EXP).toFixed(1) + ' at ★, ×' + (1 - D.EVENT_EXP).toFixed(2) + ' at ★★, ×1 at ★★★, ×' + (1 + D.EVENT_EXP).toFixed(2) + ' at ★★★★ and ×' + (1 + 2 * D.EVENT_EXP).toFixed(1) + ' at ★★★★★. District events are ★★★ or ★★★★, the District Championship ★★★★★. The Calendar shows each event\'s multiplier; the Championship has its own bonus.', 'A registration made this turn can be <b>undone</b> in the Calendar for everything it cost, until you press Continue.', 'After that it is a withdrawal: at least a month ahead for half the fee back; closer than that, no refund.', 'Any event can be skipped on the week it happens (no refund).'] },
      { icon: 'event', t: 'Championship', li: ['Regional teams qualify by winning a regional or by winning Impact, Engineering Inspiration or Rookie All-Star. Through 2024 the only other way in is a <b>wildcard</b>: when a team that has already qualified earns another place at a regional (or one team earns two there), that place goes to the finalist alliance, captain first, then first pick, then second pick. Later weeks hand out more of them. From 2025 the <b>Regional Pool</b> replaces wildcards: points from your best two regionals against a cut-off. District teams qualify through their district: its Championship places go to the District Championship\'s award winners and winning alliance, then down the points list. Last season\'s World Champions and Einstein finalists, and Hall of Fame teams, are invited.', 'From 2017 to 2020 there are two Championships (your area decides which one you attend), each with six divisions.', 'Win your division to play on <b>Einstein</b> against the other seven division champions.', 'The FIRST Impact Award is presented on Einstein. A regional Impact winner that is knocked out earlier still goes there, watches the finals from the stands and hears the announcement.', 'Use Week 7 to lighten the load so the team arrives rested.', 'The Championship opens with a ceremony after practice day (host city, divisions, the season so far), and Einstein with the emcee, the commentators and the livestream chat.'] }
    ] },
    { id: 'world', icon: 'map', name: 'World map & scouting', desc: 'Where everyone is, and how every team is doing', secs: [
      { icon: 'map', t: 'The map', li: ['The World page opens on a map of every team and event of the season. A circle is a group of teams close together: its <b>size</b> is how many, its <b>colour</b> their average strength (light blue weaker, dark blue stronger). Strength is the world simulation\'s own rating of a team: 50 is an average team, the best are in the 90s.',
        'Violet diamonds are events. <b>Your team</b> is the gold star. The events you registered for or played are ringed in gold (gold-filled once played), with a dashed line from home; your district is shaded a little stronger.',
        'Drag to move; scroll or use + and − to zoom. Click a group to zoom in, a single team for its season so far, an event for its winners. Hover anything for details.',
        'The filters above the map: teams, events or both; the area borders, the districts and the Championship cities; which teams (district, regional, rookies, qualified); a strength range; one week of events, or only yours.',
        'The table under the map lists every area and district: teams, average strength, rookies, events and Championship places so far. Click a row to find it on the map.'] },
      { icon: 'scout', t: 'Scouting', li: ['The Scouting tab lists every team\'s season so far: events played, qualification record (W-L-T), ranking score, <b>OPR</b> and its split into <b>auto</b>, <b>teleop</b> and <b>endgame</b>, best playoff finish and awards. It updates after every competition week.',
        'The events you play are measured from their matches; the rest of the world comes from the simulation, in the same game\'s points.',
        'Pick an area or a district and a kind of team, then click a column to rank by it (click again to turn the order round). The # column is the place in that list: your district sorted by OPR is your district OPR ranking.',
        'The line above the table shows where your team stands in the list on each number. <b>Your team</b> jumps to your row; type a team number to find any team.',
        'At events the Scouting tab works the same way: click a column to sort, pick an area, jump to your team. Its Auto, Teleop and Endgame columns split the OPR from that event\'s matches.'] },
      { icon: 'trophy', t: 'Championship places', li: ['The Championship places tab lists every team qualified so far, by district or regional area, with the reason on hover. Your team is in its area\'s list, highlighted.', 'Hall of Fame teams are marked HoF: they are qualified from Kickoff.'] },
      { icon: 'crown', t: 'Hall of Fame', li: ['The Hall of Fame tab lists the teams that won the FIRST Impact Award at the Championship during your career, with the season they won it.', 'Each one is invited to every Championship after that: it qualifies at Kickoff, before any event is played. A team wins the Championship Impact Award only once.'] }
    ] },
    { id: 'events', icon: 'event', name: 'At events', desc: 'Practice, scouting, incidents, playoffs', secs: [
      { icon: 'spare', t: 'Practice day', li: ['Tuning, driver reps, auto validation (Readiness shows the real Auto success chance), scouting focus, installing upgrades, or a <b>Systems Shakedown</b> that finds hidden faults and rebuilds the robot to 100%.', 'In the Stop Build Day years (2016–2019), <b>Install Upgrade</b> is how everything made since the robot was bagged gets onto it. With nothing waiting to be installed, the button is off and the block stays free.', 'A <b>Super pit</b> (Workshop) adds a full repair of one subsystem before every match, on the pre-match page.'] },
      { icon: 'scout', t: 'Scouting credibility', li: ['Your scouts\' data is usually right (90%+ at normal fatigue). Tired scouts log the wrong robot now and then.', 'A Strategy mentor, event experience and Scouting Focus practice raise it.'] },
      { icon: 'incident', t: 'Incidents', li: ['Drive-team and pit-crew mistakes: battery not swapped, wrong auto or wrong code, a loose bumper (robot disabled), a tool left inside, an unplugged joystick, uncalibrated vision, unfinished repairs.', 'At normal fatigue: at most one per event. Tired teams have many more. A Technician with good Composure prevents some. See the Incidents tab.', 'Fatigue is fixed for the whole event (Championship division and Einstein count as one).'] },
      { icon: 'team', t: 'Alliance selection and playoffs', li: ['Top 8 seeds pick alliances. The pick list comes from your own scouting: the OPR and the points your scouts saw, plus auto, climbs, breakdowns and fouls. A mixed-up scouting sheet misleads it.', 'Only a team that would captain an alliance itself can turn an invitation down, and only when it could build a stronger alliance as a captain: it weighs the inviting captain and itself (by OPR) against itself and the best team likely left at its own turn. The best robot at an event is almost never turned down. The pick list marks teams that <b>may decline</b>.', 'Through 2022, playoffs are single elimination: quarterfinals, semifinals and finals, each a best-of-three series.', 'From 2023 they are double elimination: one loss sends an alliance to the lower bracket, a second one ends its event. The finals are best of three. The bracket is drawn in the official layout, upper bracket on top.', 'A tied playoff match goes to the FRC tiebreakers (foul points, then auto and endgame points in that season\'s order). Tied on all of them, it is replayed.', 'Pit time between playoff matches follows the bracket: the matches other alliances play between two of yours, plus the break before and between finals. An upper-bracket winner gets more repair and charging time than a lower-bracket alliance on back-to-back matches. A timeout buys extra repair time.'] }
    ] },
    { id: 'matches', icon: 'play', name: 'Matches', desc: 'Coach calls, defense, faults', secs: [
      { icon: 'mentors', t: 'Coach Calls', li: ['3–6 calls a match: pace, role (score / defend / feed), target, endgame timing and level, bonus RPs, avoid contact, reset a fault.'] },
      { icon: 'play', t: 'How robots drive', li: ['Robots steer round field elements and round robots standing still. To cross the field they take the way the game leaves open: the Trench Run for a low robot (2020), a gap between two of their own Cages under the Barge (2025), a bump or a trench (2026), and another one when a stopped robot blocks it. Partners keep a gap and give way to each other: the one carrying a game piece, or heading for the endgame, keeps its line.', 'A robot that cannot get to a spot for a few seconds (a disabled partner in front of a peg, a crowd at a station) gives it up and tries another place; blocked three times in half a minute, it plays defense for a while. Partners working one plate or station use places side by side, or hold back until one is free.', 'A robot whose intake or scorer breaks for good plays defense, and a partner that was defending goes back to scoring (a defense call you made during the match stands). With nothing left to do (everything full, no game pieces), robots play defense instead of waiting.', 'Defenders go after robots that are scoring, not robots that are defending themselves, one defender to a robot; bumper to bumper they hold their ground and face the robot they guard. In autonomous, robots follow their routines as planned.'] },
      { icon: 'shield', t: 'Defense and pins', li: ['Pins last at most 5 s (through 2024) or 3 s (2025–2026), then the defender backs off six feet.', 'Protected zones: Launch Pad and late Hangar (2022), Community and Loading Zone (2023), Source, Amp, Podium and late Stage (2024), Reef and Barge Zones (2025), the Tower late in the match (2026).', 'Touching a robot at its endgame structure costs more than a foul: Traversal points for it (2022), Docked and Engaged for its alliance (2023), two tech fouls and the Ensemble RP (2024), the Barge RP (2025), Level 3 if it is off the ground (2026).', 'Before 2022: a robot crossing a defense and the Secret Passage (2016), the Key, the Retrieval Zone and the ropes late in the match (2017), the Null Territory, the Exchange and the Platform late in the match (2018), the whole HAB Zone with its Loading Stations, and the rockets in the last 20 seconds (2019), the Trench Run, Target Zone, Loading Zone and the Rendezvous Point late in the match (2020).', 'In those games, contact in the Secret Passage, the Retrieval Zone, the Null Territory and the 2020 zones is a tech foul, and touching a robot in its endgame zone hands it the climb.', 'Turrets shoot on the move and are hard to defend.', 'One defender per opponent: two robots on one is rare, and in some games a foul. In 2025 only one robot of an alliance may be on the opposing side, and in 2026 two defenders would block both bumps or both trenches, so an alliance defends with one robot at a time. A second robot told to defend scores until it may.'] },
      { icon: 'incident', t: 'Faults and falls', li: ['Low condition, low reliability, worn parts and hidden faults raise the chance of brownouts, jams and breakdowns.', 'An electrical shakedown on a second robot and an Electronics Workbench cut brownouts and comms dropouts; a network switch cuts comms dropouts further. Planetary gearboxes on the mechanism motors make breakdowns rarer.',
        '<b>The driver decides a lot of what follows.</b> A skilled driver has fewer of these accidents and a novice more; <b>Push</b> pace makes them about 60% likelier and <b>Conserve</b> 40% rarer.',
        '<b>Falls</b>: a failed high climb can end in a fall: the robot is out, badly damaged everywhere, and spare parts are scrapped. In every game from 2016 to 2020 about a quarter of failed high climbs end that way (the scale, the rope, the rung, HAB Level 3, the hang), before the climber\'s quality and the driver are counted.',
        '<b>Tipping</b>: tall lifts tip, on their own now and then and much more when a defender is leaning on them. It is worst in 2018 and 2019 (where driving skill counts most), 2023 and 2025. A tipped robot is out of the match, and the parts up high (lift, arm, shooter, climber, end effector) take a knock.',
        '<b>Beaching</b> (2020 and 2026): a robot that drives onto a ball instead of round it sits on it for two to five seconds, then frees itself; "Reset robot!" can free it sooner. In 2020 it is likeliest on the steel bars of the Shield Generator; in 2026 it is rarer overall, and likeliest on the bumps (a trench-height robot in the trench never meets one). If another robot runs into a beached robot, seven times in ten the knock frees it at once, and three times in ten it tips over.',
        '<b>Buddy climbs</b> (2018, 2019, 2020): a partner that lifts you can also drop you, and that damages your robot (the drivetrain most). Tick <b>Don\'t let a partner carry us</b> in the match plan to stay on the ground: no extra points, no risk.'] },
      { icon: 'history', t: 'Classic games (2016–2020)', li: ['<b>2016 FIRST STRONGHOLD</b>: each alliance chooses three of the defenses the other one has to cross and the audience picks a fourth (your choice is on the pre-match page). A low robot slips under the Low Bar, which stands straight across from its own Secret Passage; a blocker in its own courtyard smothers shots from the tower\'s base. Only 18 boulders are in play, and one you score rolls back out on the other alliance\'s side. Breaching is routine; capturing the tower decides the rankings.',
        '<b>2017 FIRST STEAMWORKS</b>: gears turn rotors and every robot climbs a rope. Four rotors and three climbs beat almost anything; fuel only decides matches between the very best (the boiler counts five balls a second and stops at the buzzer). A fuel system is optional, and most teams leave it out: a shooter only earns its weight on a strong, well-developed robot.',
        '<b>2018 FIRST POWER UP</b>: the Switch and the Scale score every second you own them. Cubes fed through the Exchange fill the Vault and buy Levitate, Boost and Force; the order is on the pre-match page and the drive coach plays them. Each alliance has 30 cubes.',
        '<b>2019 DESTINATION: DEEP SPACE</b>: hatch panels and cargo on the Cargo Ship and the Rockets, and a climb onto the HAB. Only the HAB Zone at each end is protected (it includes the Loading Stations), so defense in mid-field is at its strongest.',
        '<b>2020 INFINITE RECHARGE</b>: 48 Power Cells are in play and each one you score goes to the other alliance\'s Loading Bay, so two shooters and a defender is the strong line-up. A trench-height robot crosses the field under the Control Panel, where nobody may touch it; a tall one bumps over the steel bars of the Shield Generator, which wears swerve and mecanum drives. The tunnel is one robot wide and defenders wait at its mouth. One robot spins the Control Panel.',
        '<b>Buddy climbs</b>: a climber that lifts a partner is on offer in the games whose rules allowed it: 2018 (partner forks), 2019 (partner ramps to HAB Level 3) and 2020 (a partner hung from the Generator Switch). The partner has to park underneath. In 2016 every robot needs its own rung, in 2017 its own rope, and no game from 2022 on allows it.'] },
      { icon: 'scout', t: 'Season strategies', li: ['<b>2024 CRESCENDO</b>: every shooter can put notes in the Amp. Fixed shooters do it slowly and unreliably, pivot and turret shooters moderately; an amp mechanism is far better. A good human player holds Amplify until two scorers are lined up, and throws the HIGH NOTES for the Spotlight. Late in the season, alliances feed notes home from the Source end, but only from outside the opponents\' Wing (G414).', '<b>2025 REEFSCAPE</b>: the Reef has six faces with their own branches. The faces nearest the coral stations fill first; the last coral means driving around to the far side. Defenders meet a robot halfway between its station and the Reef.', '<b>2026 REBUILT</b>: fuel is tracked across the field. While their hub is inactive, alliances lob fuel from the neutral zone into their own zone (hoarding), so the next scoring shift starts with short cycles.', 'How well your alliance runs these depends on your <b>strategy read</b>: a Strategy mentor, the coach\'s Strategy, driver practice and the events you have played and scouted. Opponents pick them up over the season.'] }
    ] },
    { id: 'glossary', icon: 'help', name: 'Glossary', desc: 'Every term, in one place', secs: [
      { icon: 'event', t: 'The competition', li: [
        '<b>Alliance</b>: three teams that play a match together, red against blue. In qualifications the schedule picks them; in playoffs the captains do.',
        '<b>Alliance selection</b>: after qualifications the top eight teams (the captains) pick two partners each. A team that would captain an alliance itself may <b>decline</b> an invitation.',
        '<b>Autonomous (auto)</b>: the first 15 seconds of a match, when robots run on their own code. <b>Teleop</b>: the rest, with drivers. <b>Endgame</b>: the last 20 to 30 seconds, usually a climb.',
        '<b>Bonus RP</b>: an extra ranking point for a task in the match, such as enough climb points. <b>Ranking points (RP)</b> order the teams after qualifications.',
        '<b>Bracket</b>: the playoffs. <b>Single elimination</b> (through 2022): best-of-three series, lose one and you are out. <b>Double elimination</b> (from 2023): a second loss ends your event.',
        '<b>Championship</b>: the season\'s last event, by invitation. It is played in <b>divisions</b>; the division winners meet on <b>Einstein</b>.',
        '<b>Strength</b>: the world simulation\'s rating of a team (50 is average), shown on the World map. <b>District</b>: an area whose teams play local two-day events for <b>district points</b> and then a <b>District Championship</b>. Everyone else is a <b>regional</b> team.',
        '<b>Festival of Champions</b>: July 2017 only. The winners of the two Championships play a best of five.',
        '<b>Kickoff</b>: the day in January the game is revealed. <b>Build season</b>: the weeks from Kickoff to the first events. <b>Week 0</b>: the last build week, for scrimmages.',
        '<b>Offseason</b>: May to December. Offseason events are played with last season\'s robot.',
        '<b>Stop Build Day</b> (2016 to 2019): the day the competition robot goes in a bag until its first event.',
        '<b>The lost season</b>: 2021, which the game skips. It is the game\'s own timeline: in reality the 2020 season was stopped part-way through and its Championships were never held.',
        '<b>Wildcard</b> (through 2024) and <b>Regional Pool</b> (from 2025): the ways into the Championship for a regional team that did not win an event or a qualifying award.',
        '<b>Imp\u2060act Award</b> (called the Chairman\'s Award until 2022), <b>Engineering Inspiration</b>, <b>Rookie All-Star</b>: judged awards that qualify a team for the Championship. <b>Blue banner</b>: what an event win or that award hangs on your wall. <b>Hall of Fame</b>: the teams that won it at the Championship.'] },
      { icon: 'garage', t: 'The robot', li: [
        '<b>Subsystem</b>: one part of the robot (drivetrain, intake, lift, shooter, end effector, climber, software). <b>Concept</b>: the design you choose for it. <b>Version</b>: how many times it has been upgraded.',
        '<b>Complexity</b> (1 to 5): how hard a concept is to build. Higher means more hours and parts, and lower starting reliability. <b>Elite design</b>: the complexity 5 concept that only the best teams build.',
        '<b>Stat</b> and <b>ceiling</b>: what a subsystem can do now (Speed, Accuracy, Grip and so on), and the most that concept can ever reach. Upgrades close the gap.',
        '<b>Reliability</b>: how often a subsystem fails in a match. <b>Condition</b>: how worn it is right now (repaired with <b>spare parts</b>). <b>Hidden fault</b>: a defect nobody has found yet.',
        '<b>Hardening</b> raises reliability; <b>lightweighting</b> removes weight. The robot may weigh <b>125 lb</b>.',
        '<b>Prototype</b>: the first build of a concept or version. <b>Build copy</b>: another unit of a finished design, for the second robot or as a spare. <b>Fabrication</b>: copies, which use hours but no project slot. <b>Program projects</b>: the Impact and Woodie Flowers essays and the Knowledge Base, which take no slot either. <b>Finish now card</b>: a top-level facility\'s once-a-season shortcut.',
        '<b>Competition robot</b>: the one of your two robots that goes to events. <b>Test chassis</b>: a drivetrain on the other robot (a copy of yours, or a basic kit one) for early testing and practice. <b>Event spare</b>: a unit identical to the competition robot\'s.',
        '<b>Kit of Parts (KOP)</b>: the free parts every team gets at Kickoff. <b>KOP voucher</b>: one free KOP subsystem kit, handed out at Kickoff. <b>COTS</b>: commercial off-the-shelf parts and kits. <b>Control system</b>: the motors, encoders and control hub, from one vendor if you can. <b>Vendors</b>: Sterling Motion (to 2019), Apex Motion (from 2020) and Lumen Robotics; <b>Lanternworks</b> for vision hardware (from 2018).',
        '<b>Planetary gearbox</b>: a sealed gearbox for one mechanism motor (optional, fewer breakdowns). <b>Network switch</b>: links camera, controller and radio (fewer comms dropouts). <b>ML accelerator</b>: runs object detection on the robot. <b>Servo kit</b>: servos and actuators that do what small cylinders did.',
        '<b>Kit chassis</b>, <b>West Coast drive</b> (six or eight wheels, tank steering), <b>mecanum</b> and <b>swerve</b>: the drivetrains, from simplest to best. Mecanum and swerve are <b>holonomic</b>: they can move sideways.',
        '<b>Turret</b>: a mechanism that turns independently of the chassis. <b>Hood</b>: the adjustable part of a shooter that sets the angle. <b>Elevator</b>, <b>arm</b>, <b>wrist</b>, <b>telescope</b>: the ways to lift. <b>End effector</b>: the claw or gripper at the end of the lift. <b>Indexer</b>: what queues game pieces for a shooter.',
        '<b>Low centre of gravity</b>: weight carried low, so the robot does not tip.',
        '<b>Tech Knowledge</b>: what the program knows how to build, by area (twelve of them, from Swerve Drive to End Effectors), in levels 0 to 5. <b>Core areas</b>: the ones a concept needs. <b>Knowledge Base</b>: a project that slows the fading, updated yearly.'] },
      { icon: 'clock', t: 'Hours and projects', li: [
        '<b>Team hours</b>: what the students can work in a turn. Projects share them. <b>Project slot</b>: how many projects can run at once (mentors and facilities add slots).',
        '<b>Effort</b>: Rush (60% of the hours, weaker, 15% more materials), Standard, or Thorough (140% of the hours, better, 10% less material).',
        '<b>Extra hours</b>: idle hours put into a project to raise its quality. <b>Overtime</b>: 30% more hours for a build week, paid for in morale and fatigue.',
        '<b>Fatigue</b>: how tired the team is. It causes <b>incidents</b> at events and makes scouting less reliable. About 10% idle hours a week holds it steady.',
        '<b>Testing hours</b>: time on a test chassis, second robot or Practice Field, split between <b>development testing</b> (better projects) and <b>driver practice</b>.',
        '<b>Familiarity</b>: how well the drive team knows each mechanism. <b>Tuning</b> and <b>confidence</b>: how settled the robot and its drivers are at an event.',
        '<b>Defense drills</b> and the <b>electrical shakedown</b>: what a running second robot adds. <b>Systems Shakedown</b>: a practice-day block that finds hidden faults and restores the robot.'] },
      { icon: 'play', t: 'Matches', li: [
        '<b>Match plan</b>: role, target, pace and endgame, set before a match. <b>Coach Calls</b>: the few changes you may make during it.',
        '<b>Pace</b>: Push (faster, more fouls, wear and accidents), Balanced, or Conserve.',
        '<b>Cycle</b>: one trip to collect a game piece and score it. <b>OPR</b>: an estimate of the points one robot adds to its alliance; split by match period it gives auto, teleop and endgame OPR. <b>Ranking score (RS)</b>: average ranking points per qualification match.',
        '<b>Defense</b>: getting in an opponent\'s way. <b>Pin</b>: holding a robot against something, limited to a few seconds. <b>Protected zone</b>: where touching an opponent is a foul.',
        '<b>Foul</b> and <b>tech foul</b>: penalties, paid in points to the other alliance.',
        '<b>Brownout</b>: the battery sags and the robot stalls for a moment. <b>Comms dropout</b>: the robot loses its link. <b>Jam</b>: an intake or scorer is stuck for a while.',
        '<b>Tip</b>: the robot falls over and is out; what stands up high is damaged a little. <b>Fall</b>: it drops from a high climb, badly damaged. <b>Beaching</b> (2020, 2026): it sits on a ball for a few seconds.',
        '<b>Buddy climb</b> (2018, 2019, 2020): one robot lifts a partner in the endgame.',
        '<b>Human player</b>: the student who feeds game pieces to the robot (in 2024 also the one who presses Amplify and throws the HIGH NOTES). <b>Amplify</b> (2024): ten seconds of 5-point Speaker notes. <b>Spotlight</b> (2024): a HIGH NOTE on a microphone, +1 for each robot onstage below it. <b>Drive coach</b>: the one who calls the strategy. <b>Technician</b>: the optional fifth member, for the pit.',
        '<b>Scouting credibility</b>: how far your scouts\' numbers can be trusted. <b>Pick list</b>: your order of preference at alliance selection.',
        '<b>Strategy read</b>: how well your alliance plays a season\'s advanced strategies (feeding, hoarding, splitting stations).',
        '<b>Tiebreaker</b>: how a tied playoff match is decided before it is replayed.'] },
      { icon: 'team', t: 'The program', li: [
        '<b>Program Support</b>: the school\'s backing, moved by the season goals. At 0 the program is cut. It also decides your <b>workshop space</b>.',
        '<b>Reputation</b>: what the wider community thinks of the team. It brings sponsors, recruits and invitations, and raises the school\'s expectations.',
        '<b>Morale</b>: how the students feel. <b>Legacy</b>: the career score on the History page.',
        '<b>Sponsor satisfaction</b>: decides renewals and donations. <b>Loyalty level</b>: your standing with a parts vendor.',
        '<b>Feeder program</b>: an FLL or FTC team, camp or club that sends you recruits. <b>Impact rating</b>: your chance at the Impact Award, built from several seasons of outreach.',
        '<b>STEM support fund</b>: emergency money for a nearly broke team, at a cost in reputation.',
        '<b>Facility</b>: a workshop machine or room. Facilities speed projects up, wear down, and take floor space. <b>Super pit</b>: the top level of Pit Setup, a pit in road cases.'] }
    ] }
  ];
  UI.HELP_CATS = CATS;
  // topic or "topic#Section title" (the small ? beside a text): the category, scrolled to that section
  // a "?" opens the guide; a window it was clicked in is put away while you read and comes back with Back
  UI.A.helpTopic = t => {
    const p = String(t || '').split('#'), c = CATS.some(x => x.id === p[0]) ? p[0] : 'basics';
    if (UI.screen !== 'help') UI.helpReturn = { screen: UI.screen, p: UI.p, modal: document.getElementById('modal') ? UI._modal : null };
    UI.closeModal();
    UI.go('help', { cat: c, sec: p[1] || null });
  };
  UI.A.helpBack = () => {
    const r = UI.helpReturn; UI.helpReturn = null;
    if (!r || !r.screen || r.screen === 'help') return UI.A.back();
    UI.go(r.screen, r.p);
    if (r.modal) UI.modal(r.modal.html, r.modal.opts);
  };
  UI.A.helpCat = c => { UI.p.cat = c; UI.p.sec = null; UI.render(); const m = document.querySelector('.menu-box'); if (m) m.scrollIntoView({ block: 'start' }); };
  UI.A.tutAgain = () => { UI.A.back(); setTimeout(() => Tut.start('season', true), 80); };
  UI.A.tutToggle = v => { Tut.setEnabled(!!v); UI.render(); };
  UI.S.help = { full: true, after() { const el = document.querySelector('.help-sec.at'); if (el && !UI.p.secSeen) { UI.p.secSeen = 1; el.scrollIntoView({ block: 'center' }); } }, html() {
    const cur = CATS.find(c => c.id === (UI.p.cat || 'basics')) || CATS[0];
    let o = '<div class="menu-wrap"><div class="menu-box" style="max-width:980px"><div class="row"><div class="logo" style="font-size:28px">How to play</div><span class="tag" style="margin-left:10px">v' + h(G.VERSION) + '</span><span class="sp"></span>' +
      (G.S && G.S.team ? '<button class="btn" data-act="tutAgain">' + ic('play', 14) + ' Replay the tour</button>' : '') + '<button class="btn" data-act="helpBack">Back</button></div>' +
      '<label class="row sm muted mt"><input type="checkbox" data-chg="tutToggle" ' + (Tut.enabled() ? 'checked' : '') + '> Show tutorials (a short tour once per game: at your first Kickoff, first event and first match)</label>';
    o += '<div class="help-grid mt">' + CATS.map(c => '<button class="help-cat ' + (c === cur ? 'on' : '') + '" data-act="helpCat" data-arg="' + c.id + '">' + ic(c.icon, 22) + '<div><div class="b">' + h(c.name) + '</div><div class="xs muted">' + h(c.desc) + '</div></div></button>').join('') + '</div>';
    o += '<h2 class="mt">' + ic(cur.icon, 20) + ' ' + h(cur.name) + '</h2>' + cur.secs.map(s => '<div class="help-sec' + (UI.p.sec && s.t === UI.p.sec ? ' at' : '') + '"><h3>' + ic(s.icon, 18) + h(s.t) + '</h3>' + U.infl(s.d || '') + '<ul>' + s.li.map(x => '<li>' + U.infl(x) + '</li>').join('') + '</ul></div>').join('');
    return o + '</div></div>';
  } };
})();
